{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Ensure basic roles are not used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The role 'roles/editor' is a basic role that grants broad permissions and should be avoided. Using basic roles increases the risk of privilege escalation and unauthorized access."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/custom.tradingPlatformAdmin\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced the basic role 'roles/editor' with a placeholder custom role 'roles/custom.tradingPlatformAdmin' to avoid using overly permissive roles."
}
